-- Abyss: Hyprland visual layer. Generated by rice-render from palette.toml.
-- Loaded from hyprland.lua via ~/.local/share/rice/active/hypr.lua.

-- Windows are wet glass floating over the reef: dark, a little see-through,
-- blurred, edged by a thin teal-into-violet line. Abyss has one mode, but the
-- colours still sit in hypr-mode.lua like every rice's, so `rice mode` and a
-- reload see the same split.

hl.config({
    general = {
        gaps_in     = {{ shape.gaps_in }},
        gaps_out    = {{ shape.gaps_out }},
        border_size = {{ shape.border }},
    },

    decoration = {
        rounding         = {{ shape.window }},
        rounding_power   = {{ shape.rounding_power }},
        active_opacity   = 1.0,
        dim_inactive     = false,

        -- underwater: a soft wide blur, darkened, the glows lifted a little
        blur = {
            enabled           = true,
            size              = 8,
            passes            = 3,
            noise             = 0.02,
            contrast          = 1.0,
            vibrancy_darkness = 0.3,
            popups            = true,
            xray              = false,
        },

        shadow = {
            enabled      = true,
            render_power = 3,
        },
    },

    group = {
        groupbar = {
            enabled           = true,
            height            = 18,
            indicator_height  = 0,
            gradients         = true,
            rounding          = {{ shape.chip }},
            gradient_rounding = {{ shape.chip }},
            round_only_edges  = false,
            gradient_round_only_edges = false,
            font_family       = "{{ fonts.ui }}",
            font_size         = 11,
            font_weight_active   = {{ fonts.weight_strong }},
            font_weight_inactive = {{ fonts.weight }},
        },
    },

    animations = { enabled = true },
})

---------------------------------------------------------------------------
-- Motion: everything drifts; arrivals settle, dismissals sink
---------------------------------------------------------------------------
hl.curve("drift",  { type = "bezier", points = { { {{ motion.bloom.0 }}, {{ motion.bloom.1 }} },  { {{ motion.bloom.2 }}, {{ motion.bloom.3 }} } } })
hl.curve("settle", { type = "bezier", points = { { {{ motion.settle.0 }}, {{ motion.settle.1 }} }, { {{ motion.settle.2 }}, {{ motion.settle.3 }} } } })
hl.curve("sink",   { type = "bezier", points = { { {{ motion.sink.0 }}, {{ motion.sink.1 }} },   { {{ motion.sink.2 }}, {{ motion.sink.3 }} } } })
hl.curve("linear", { type = "bezier", points = { { 0, 0 }, { 1, 1 } } })

-- speed is in deciseconds
hl.animation({ leaf = "windowsIn",    enabled = true, speed = {{ motion.open | div(100) }},       bezier = "settle", style = "popin 96%" })
hl.animation({ leaf = "windowsOut",   enabled = true, speed = {{ motion.close | div(100) }},      bezier = "sink",   style = "popin 94%" })
hl.animation({ leaf = "windowsMove",  enabled = true, speed = {{ motion.move | div(100) }},       bezier = "settle" })
hl.animation({ leaf = "fadeIn",       enabled = true, speed = {{ motion.open | div(100) }},       bezier = "drift" })
hl.animation({ leaf = "fadeOut",      enabled = true, speed = {{ motion.close | div(100) }},      bezier = "sink" })
hl.animation({ leaf = "fadeSwitch",   enabled = true, speed = {{ motion.focus | div(100) }},      bezier = "drift" })
hl.animation({ leaf = "border",       enabled = true, speed = {{ motion.focus | div(100) }},      bezier = "drift" })
hl.animation({ leaf = "borderangle",  enabled = true, speed = {{ motion.border_loop | div(100) | min(100) }}, bezier = "linear", style = "loop" })
-- workspaces: a slow fade-slide through the water
hl.animation({ leaf = "workspaces",   enabled = true, speed = {{ motion.workspace | div(100) }},  bezier = "drift",  style = "slidefade 12%" })
hl.animation({ leaf = "specialWorkspace", enabled = true, speed = {{ motion.scratchpad | div(100) }}, bezier = "drift", style = "slidefadevert 20%" })
-- Quickshell animates its own panels; Hyprland only fades unknown layers
hl.animation({ leaf = "layers",       enabled = true, speed = 3, bezier = "drift", style = "fade" })

---------------------------------------------------------------------------
-- Styling the base layer's window tags
---------------------------------------------------------------------------
-- forced opaque: browsers, video, images, editors, games
hl.window_rule({ name = "abyss-opaque", match = { tag = "opaque" }, opacity = "1.0 override 1.0 override" })
-- glassy: terminals, files, music, system tools show the reef through them
hl.window_rule({ name = "abyss-glassy", match = { tag = "glassy" }, opacity = "{{ opacity.active }} override {{ opacity.inactive }} override" })
-- floating dialogs: the panels' rounding
hl.window_rule({ name = "abyss-dialog", match = { tag = "dialog" }, rounding = {{ shape.panel }} })
-- picture-in-picture: no border
hl.window_rule({ name = "abyss-pip", match = { tag = "pip" }, border_size = 0, no_shadow = true })
-- fullscreen: no border or rounding
hl.window_rule({ name = "abyss-fullscreen", match = { fullscreen = true }, border_size = 0, rounding = 0 })
-- games: no animations, blur or shadow; always opaque
hl.window_rule({
    name = "abyss-game", match = { tag = "game" },
    no_anim = true, no_blur = true, no_shadow = true, opacity = "1.0 override 1.0 override",
})

---------------------------------------------------------------------------
-- Quickshell surfaces: the glass blurs the reef behind it
---------------------------------------------------------------------------
hl.layer_rule({
    name = "abyss-glass", match = { namespace = "^abyss-(bar|launcher|island|center|osd|power|toast|keys|stats|deskcard|deskpanel)$" },
    blur = true, ignore_alpha = 0.2, no_anim = true,
})
hl.layer_rule({ name = "abyss-wallpaper", match = { namespace = "^abyss-wallpaper$" }, no_anim = true })

---------------------------------------------------------------------------
-- The colours: borders, glass, shadows (beside this file in build/dark/)
---------------------------------------------------------------------------
local here = debug.getinfo(1, "S").source:match("^@(.*/)") or
    ((os.getenv("XDG_DATA_HOME") or (os.getenv("HOME") .. "/.local/share")) .. "/rice/active/")
dofile(here .. "hypr-mode.lua")
